    /// Connects a model to a port: subscribes every state stream and builds the model from their replayed values,
    /// then subscribes the lists and event streams (a list's replay arrives before this returns). A state stream
    /// that replays nothing is a contract defect.
    public static func connect(_ port: OahuPort) throws -> GeneratorModel {
        try connect(OahuConnection(port: port))
    }

    /// `connect(_:)` over a connection you made.
    public static func connect(_ connection: OahuConnection) throws -> GeneratorModel {
        // Each stream decodes a whole message in `read`; the connection checks every byte was read, and only then is
        // the value applied (to the model, if it is still there). A bad message leaves every value unchanged, though
        // observers may see one change notification for it.
        let copySubscription = connection.subscribeState(GeneratorContract.Stream.copy, read: GeneratorCopy.read)
        let paletteSubscription = connection.subscribeState(GeneratorContract.Stream.palette, read: AppPalette.read)
        let layoutSubscription = connection.subscribeState(GeneratorContract.Stream.layout, read: GeneratorLayout.read)
        let locksSubscription = connection.subscribeState(
            GeneratorContract.Stream.locks,
            read: GeneratorPolicyLocks.read)
        let generatedSubscription = connection.subscribeState(
            GeneratorContract.Stream.generated,
            read: { try $0.readList(TextRun.read) })
        let kindSubscription = connection.subscribeState(GeneratorContract.Stream.kind, read: GeneratorKind.read)
        let passwordTypeSubscription = connection.subscribeState(
            GeneratorContract.Stream.passwordType,
            read: PasswordKind.read)
        let lengthSubscription = connection.subscribeState(
            GeneratorContract.Stream.length,
            read: { Int(try $0.readInt()) })
        let uppercaseSubscription = connection.subscribeState(
            GeneratorContract.Stream.uppercase,
            read: { try $0.readBool() })
        let lowercaseSubscription = connection.subscribeState(
            GeneratorContract.Stream.lowercase,
            read: { try $0.readBool() })
        let numbersSubscription = connection.subscribeState(
            GeneratorContract.Stream.numbers,
            read: { try $0.readBool() })
        let specialSubscription = connection.subscribeState(
            GeneratorContract.Stream.special,
            read: { try $0.readBool() })
        let minNumbersSubscription = connection.subscribeState(
            GeneratorContract.Stream.minNumbers,
            read: { Int(try $0.readInt()) })
        let minSpecialSubscription = connection.subscribeState(
            GeneratorContract.Stream.minSpecial,
            read: { Int(try $0.readInt()) })
        let avoidAmbiguousSubscription = connection.subscribeState(
            GeneratorContract.Stream.avoidAmbiguous,
            read: { try $0.readBool() })
        let numberOfWordsSubscription = connection.subscribeState(
            GeneratorContract.Stream.numberOfWords,
            read: { Int(try $0.readInt()) })
        let wordSeparatorSubscription = connection.subscribeState(
            GeneratorContract.Stream.wordSeparator,
            read: { try $0.readString() })
        let capitalizeSubscription = connection.subscribeState(
            GeneratorContract.Stream.capitalize,
            read: { try $0.readBool() })
        let includeNumberSubscription = connection.subscribeState(
            GeneratorContract.Stream.includeNumber,
            read: { try $0.readBool() })
        let usernameTypeSubscription = connection.subscribeState(
            GeneratorContract.Stream.usernameType,
            read: UsernameKind.read)
        let plusAddressedEmailSubscription = connection.subscribeState(
            GeneratorContract.Stream.plusAddressedEmail,
            read: { try $0.readString() })
        let plusAddressedEmailTypeSubscription = connection.subscribeState(
            GeneratorContract.Stream.plusAddressedEmailType,
            read: EmailKind.read)
        let catchAllDomainSubscription = connection.subscribeState(
            GeneratorContract.Stream.catchAllDomain,
            read: { try $0.readString() })
        let catchAllEmailTypeSubscription = connection.subscribeState(
            GeneratorContract.Stream.catchAllEmailType,
            read: EmailKind.read)
        let serviceSubscription = connection.subscribeState(
            GeneratorContract.Stream.service,
            read: ForwardedService.read)
        let apiSecretSubscription = connection.subscribeState(
            GeneratorContract.Stream.apiSecret,
            read: { try $0.readString() })
        let addyIoDomainSubscription = connection.subscribeState(
            GeneratorContract.Stream.addyIoDomain,
            read: { try $0.readString() })
        let forwardEmailDomainSubscription = connection.subscribeState(
            GeneratorContract.Stream.forwardEmailDomain,
            read: { try $0.readString() })
        let capitalizeRandomWordSubscription = connection.subscribeState(
            GeneratorContract.Stream.capitalizeRandomWord,
            read: { try $0.readBool() })
        let includeNumberRandomWordSubscription = connection.subscribeState(
            GeneratorContract.Stream.includeNumberRandomWord,
            read: { try $0.readBool() })
        let model: GeneratorModel
        do {
            model = GeneratorModel(
                connection: connection,
                copy: try copySubscription.initialValue(),
                palette: try paletteSubscription.initialValue(),
                layout: try layoutSubscription.initialValue(),
                locks: try locksSubscription.initialValue(),
                generated: try generatedSubscription.initialValue(),
                kind: try kindSubscription.initialValue(),
                passwordType: try passwordTypeSubscription.initialValue(),
                length: try lengthSubscription.initialValue(),
                uppercase: try uppercaseSubscription.initialValue(),
                lowercase: try lowercaseSubscription.initialValue(),
                numbers: try numbersSubscription.initialValue(),
                special: try specialSubscription.initialValue(),
                minNumbers: try minNumbersSubscription.initialValue(),
                minSpecial: try minSpecialSubscription.initialValue(),
                avoidAmbiguous: try avoidAmbiguousSubscription.initialValue(),
                numberOfWords: try numberOfWordsSubscription.initialValue(),
                wordSeparator: try wordSeparatorSubscription.initialValue(),
                capitalize: try capitalizeSubscription.initialValue(),
                includeNumber: try includeNumberSubscription.initialValue(),
                usernameType: try usernameTypeSubscription.initialValue(),
                plusAddressedEmail: try plusAddressedEmailSubscription.initialValue(),
                plusAddressedEmailType: try plusAddressedEmailTypeSubscription.initialValue(),
                catchAllDomain: try catchAllDomainSubscription.initialValue(),
                catchAllEmailType: try catchAllEmailTypeSubscription.initialValue(),
                service: try serviceSubscription.initialValue(),
                apiSecret: try apiSecretSubscription.initialValue(),
                addyIoDomain: try addyIoDomainSubscription.initialValue(),
                forwardEmailDomain: try forwardEmailDomainSubscription.initialValue(),
                capitalizeRandomWord: try capitalizeRandomWordSubscription.initialValue(),
                includeNumberRandomWord: try includeNumberRandomWordSubscription.initialValue())
        } catch {
            connection.close()
            throw error
        }
        copySubscription.bind { [weak model] in model?.copy = $0 }
        paletteSubscription.bind { [weak model] in model?.palette = $0 }
        layoutSubscription.bind { [weak model] in model?.layout = $0 }
        locksSubscription.bind { [weak model] in model?.locks = $0 }
        generatedSubscription.bind { [weak model] in model?.generated = $0 }
        kindSubscription.bind { [weak model] in model?.kindValue = $0 }
        passwordTypeSubscription.bind { [weak model] in model?.passwordTypeValue = $0 }
        lengthSubscription.bind { [weak model] in model?.lengthValue = $0 }
        uppercaseSubscription.bind { [weak model] in model?.uppercaseValue = $0 }
        lowercaseSubscription.bind { [weak model] in model?.lowercaseValue = $0 }
        numbersSubscription.bind { [weak model] in model?.numbersValue = $0 }
        specialSubscription.bind { [weak model] in model?.specialValue = $0 }
        minNumbersSubscription.bind { [weak model] in model?.minNumbersValue = $0 }
        minSpecialSubscription.bind { [weak model] in model?.minSpecialValue = $0 }
        avoidAmbiguousSubscription.bind { [weak model] in model?.avoidAmbiguousValue = $0 }
        numberOfWordsSubscription.bind { [weak model] in model?.numberOfWordsValue = $0 }
        wordSeparatorSubscription.bind { [weak model] in model?.wordSeparatorValue = $0; model?.wordSeparatorHeld.clear() }
        capitalizeSubscription.bind { [weak model] in model?.capitalizeValue = $0 }
        includeNumberSubscription.bind { [weak model] in model?.includeNumberValue = $0 }
        usernameTypeSubscription.bind { [weak model] in model?.usernameTypeValue = $0 }
        plusAddressedEmailSubscription.bind { [weak model] in model?.plusAddressedEmailValue = $0; model?.plusAddressedEmailHeld.clear() }
        plusAddressedEmailTypeSubscription.bind { [weak model] in model?.plusAddressedEmailTypeValue = $0 }
        catchAllDomainSubscription.bind { [weak model] in model?.catchAllDomainValue = $0; model?.catchAllDomainHeld.clear() }
        catchAllEmailTypeSubscription.bind { [weak model] in model?.catchAllEmailTypeValue = $0 }
        serviceSubscription.bind { [weak model] in model?.serviceValue = $0 }
        apiSecretSubscription.bind { [weak model] in model?.apiSecretValue = $0; model?.apiSecretHeld.clear() }
        addyIoDomainSubscription.bind { [weak model] in model?.addyIoDomainValue = $0; model?.addyIoDomainHeld.clear() }
        forwardEmailDomainSubscription.bind { [weak model] in model?.forwardEmailDomainValue = $0; model?.forwardEmailDomainHeld.clear() }
        capitalizeRandomWordSubscription.bind { [weak model] in model?.capitalizeRandomWordValue = $0 }
        includeNumberRandomWordSubscription.bind { [weak model] in model?.includeNumberRandomWordValue = $0 }
        connection.subscribe(GeneratorContract.Stream.copied, read: { _ in () }) { [weak model] in
            model?.copied.send($0)
        }
        return model
    }

    /// Sends the CopyValue intent. Observe state and events for its effects.
    public func copyValue() {
        connection.call(GeneratorContract.Member.copyValue) { _ in }
    }

    /// Sends the Regenerate intent. Observe state and events for its effects.
    public func regenerate() {
        connection.call(GeneratorContract.Member.regenerate) { _ in }
    }

    /// Sends the LengthEditingEnded intent. Observe state and events for its effects.
    public func lengthEditingEnded() {
        connection.call(GeneratorContract.Member.lengthEditingEnded) { _ in }
    }

    /// Sends the ToggleApiSecret intent. Observe state and events for its effects.
    public func toggleApiSecret() {
        connection.call(GeneratorContract.Member.toggleApiSecret) { _ in }
    }

    /// Sends the ShowUsernameTypeHelp intent. Observe state and events for its effects.
    public func showUsernameTypeHelp() {
        connection.call(GeneratorContract.Member.showUsernameTypeHelp) { _ in }
    }

    /// Unsubscribes everything, drops the port and ends every event stream. Idempotent.
    public func close() {
        connection.close()
        wordSeparatorHeld.clear()
        plusAddressedEmailHeld.clear()
        catchAllDomainHeld.clear()
        apiSecretHeld.clear()
        addyIoDomainHeld.clear()
        forwardEmailDomainHeld.clear()
        copied.finish()
    }
}

// MARK: - Preview

extension GeneratorModel {
    /// Configures the Generator preview (P1-D15), in the contract's own types: `on…` handlers answer the screen's
    /// methods and edits; `set…`, `update…` and `emit…` publish later updates. `preview(...)` hands
    /// one to `configure` before the model connects: a state set there is the value the model starts with, but list
    /// edits and events published there reach nothing, since nothing listens yet. Keep it, or use it from a handler,
    /// for those.
    @MainActor
    public struct Preview {
        /// The raw preview port, for anything the typed members don't cover.
        public let port: OahuPreviewPort

        fileprivate init(port: OahuPreviewPort) {
            self.port = port
        }

        /// Answers edits of Kind: gets the proposed value and returns the value to publish (the proposal, a
        /// normalized value, or the current one to refuse it). The default accepts every edit. The answer is published
        /// before the edit returns, as in C#; a thrown error stops the preview.
        public func onEditKind(_ handler: @escaping (GeneratorKind) throws -> GeneratorKind) {
            port.onEdit(
                member: GeneratorContract.Member.kind,
                stream: GeneratorContract.Stream.kind,
                read: GeneratorKind.read,
                write: GeneratorKind.write,
                handler)
        }

        /// Answers edits of PasswordType: gets the proposed value and returns the value to publish (the proposal, a
        /// normalized value, or the current one to refuse it). The default accepts every edit. The answer is published
        /// before the edit returns, as in C#; a thrown error stops the preview.
        public func onEditPasswordType(_ handler: @escaping (PasswordKind) throws -> PasswordKind) {
            port.onEdit(
                member: GeneratorContract.Member.passwordType,
                stream: GeneratorContract.Stream.passwordType,
                read: PasswordKind.read,
                write: PasswordKind.write,
                handler)
        }

        /// Answers edits of Length: gets the proposed value and returns the value to publish (the proposal, a
        /// normalized value, or the current one to refuse it). The default accepts every edit. The answer is published
        /// before the edit returns, as in C#; a thrown error stops the preview.
        public func onEditLength(_ handler: @escaping (Int) throws -> Int) {
            port.onEdit(
                member: GeneratorContract.Member.length,
                stream: GeneratorContract.Stream.length,
                read: { Int(try $0.readInt()) },
                write: { $0.writeInt($1) },
                handler)
        }

        /// Answers edits of Uppercase: gets the proposed value and returns the value to publish (the proposal, a
