// MARK: - Screen provider

@objc(OAHUScreen_bd3ec26ce8f07265b522542858ac4f92229ba2cc46987475f97d7ac98bc8dd7f)
public final class GeneratorScreenProvider: NSObject, ScreenProvider {
    private static let log = Logger(subsystem: "OahuRuntime", category: "screens")

    public func contractHash(_ contract: String) -> Int64 {
        contract == GeneratorContract.name ? GeneratorContract.hash : 0
    }

    public func createScreen(_ contract: String, hash: Int64, port: OahuPort) -> ScreenHandle? {
        guard contract == GeneratorContract.name else { return nil }
        guard hash == GeneratorContract.hash, port.contractHash == hash, port.contractName == contract else {
            Self.log.error("Refusing \(contract, privacy: .public): the port's hash is \(port.contractHash), this library was built against \(GeneratorContract.hash)")
            return nil
        }
        let model: GeneratorModel
        do {
            model = try GeneratorModel.connect(port)
        } catch {
            Self.log.error("Generator could not connect: \(error, privacy: .public)")
            return nil
        }
        return OahuScreen(rootView: GeneratorScreen(model: model)) { model.close() }
    }
}
